                        ret["comment"] = event_ret["comment"]
                    else:
                        ret["result"] = False
                        ret["comment"] = (
                            "Did not receive the beacon add complete event before the"
                            " timeout of {}s".format(
                                kwargs.get("timeout", default_event_wait)
